CREATE TABLE "GovernanceControlRecord" (
 id text PRIMARY KEY,kind text NOT NULL, "ownerEmail" text NOT NULL,"approverEmail" text NOT NULL,"affectedControls" text[] NOT NULL,rationale text NOT NULL,"compatibilityImpact" text NOT NULL,evidence jsonb NOT NULL,"expiresAt" timestamptz,"remediationAt" timestamptz,digest text NOT NULL UNIQUE,"createdAt" timestamptz NOT NULL DEFAULT clock_timestamp(),
 CONSTRAINT governance_kind_ck CHECK(kind IN('AMENDMENT','EXCEPTION')),CONSTRAINT governance_independent_ck CHECK("ownerEmail"<>"approverEmail"),CONSTRAINT governance_exception_expiry_ck CHECK(kind<>'EXCEPTION' OR ("expiresAt" IS NOT NULL AND "remediationAt" IS NOT NULL AND "remediationAt"<="expiresAt")));
CREATE TABLE "MaterialApproval" (id text PRIMARY KEY,action text NOT NULL,target text NOT NULL,"payloadHash" text NOT NULL,"requestedBy" text NOT NULL,"approvedBy" text,state text NOT NULL DEFAULT 'PENDING',"expiresAt" timestamptz NOT NULL,"executedAt" timestamptz,"createdAt" timestamptz NOT NULL DEFAULT clock_timestamp(),CONSTRAINT material_hash_ck CHECK("payloadHash"~'^[0-9a-f]{64}$'),CONSTRAINT material_state_ck CHECK(state IN('PENDING','APPROVED','EXECUTED','EXPIRED')),CONSTRAINT material_independent_ck CHECK("approvedBy" IS NULL OR "approvedBy"<>"requestedBy"));
CREATE INDEX "MaterialApproval_state_expires_idx" ON "MaterialApproval"(state,"expiresAt");
CREATE TABLE "GovernedRepairCommand" (id text PRIMARY KEY,"propertyId" text NOT NULL REFERENCES "Property"(id) ON DELETE RESTRICT,"commandType" text NOT NULL,"idempotencyKey" text NOT NULL UNIQUE,"expectedVersion" integer NOT NULL,reason text NOT NULL,payload jsonb NOT NULL,"payloadHash" text NOT NULL,status text NOT NULL DEFAULT 'QUEUED',"requestedBy" text NOT NULL,result jsonb,"createdAt" timestamptz NOT NULL DEFAULT clock_timestamp(),"completedAt" timestamptz,CONSTRAINT repair_type_ck CHECK("commandType" IN('RECRAWL','REINDEX','VALIDATE','RECONCILE_DELIVERY')),CONSTRAINT repair_hash_ck CHECK("payloadHash"~'^[0-9a-f]{64}$'),CONSTRAINT repair_status_ck CHECK(status IN('QUEUED','RUNNING','SUCCEEDED','FAILED')));
CREATE INDEX "GovernedRepairCommand_property_status_created_idx" ON "GovernedRepairCommand"("propertyId",status,"createdAt");
CREATE TABLE "BreakGlassGrant" (id text PRIMARY KEY,"incidentId" text NOT NULL,"actorEmail" text NOT NULL,scopes text[] NOT NULL,reason text NOT NULL,"expiresAt" timestamptz NOT NULL,"reviewedBy" text,"reviewedAt" timestamptz,"createdAt" timestamptz NOT NULL DEFAULT clock_timestamp(),CONSTRAINT breakglass_incident_ck CHECK("incidentId"~'^INC-[A-Z0-9-]{4,}$'),CONSTRAINT breakglass_expiry_ck CHECK("expiresAt">"createdAt" AND "expiresAt"<="createdAt"+interval '1 hour'),CONSTRAINT breakglass_review_ck CHECK("reviewedBy" IS NULL OR "reviewedBy"<>"actorEmail"));
CREATE INDEX "BreakGlassGrant_actor_expires_idx" ON "BreakGlassGrant"("actorEmail","expiresAt"); CREATE INDEX "BreakGlassGrant_incident_idx" ON "BreakGlassGrant"("incidentId");

ALTER TABLE "GovernanceControlRecord" ENABLE ROW LEVEL SECURITY; ALTER TABLE "GovernanceControlRecord" FORCE ROW LEVEL SECURITY;
ALTER TABLE "MaterialApproval" ENABLE ROW LEVEL SECURITY; ALTER TABLE "MaterialApproval" FORCE ROW LEVEL SECURITY;
ALTER TABLE "GovernedRepairCommand" ENABLE ROW LEVEL SECURITY; ALTER TABLE "GovernedRepairCommand" FORCE ROW LEVEL SECURITY;
ALTER TABLE "BreakGlassGrant" ENABLE ROW LEVEL SECURITY; ALTER TABLE "BreakGlassGrant" FORCE ROW LEVEL SECURITY;
CREATE POLICY platform_admin_governance ON "GovernanceControlRecord" FOR SELECT TO aifrogi_platform_admin USING(current_setting('app.system_purpose',true)='PLATFORM_ADMIN');
CREATE POLICY platform_admin_approval ON "MaterialApproval" FOR SELECT TO aifrogi_platform_admin USING(current_setting('app.system_purpose',true)='PLATFORM_ADMIN');
CREATE POLICY platform_admin_repair ON "GovernedRepairCommand" FOR SELECT TO aifrogi_platform_admin USING(current_setting('app.system_purpose',true)='PLATFORM_ADMIN');
CREATE POLICY platform_admin_breakglass ON "BreakGlassGrant" FOR SELECT TO aifrogi_platform_admin USING(current_setting('app.system_purpose',true)='PLATFORM_ADMIN');
REVOKE ALL ON "GovernanceControlRecord","MaterialApproval","GovernedRepairCommand","BreakGlassGrant" FROM PUBLIC,aifrogi_web,aifrogi_public,aifrogi_worker,aifrogi_publisher,aifrogi_platform_admin;
GRANT SELECT ON "GovernanceControlRecord","MaterialApproval","GovernedRepairCommand","BreakGlassGrant" TO aifrogi_platform_admin;
GRANT USAGE ON SCHEMA aifrogi_security TO aifrogi_platform_admin;

CREATE FUNCTION aifrogi_security.require_platform_admin(p_actor text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN IF session_user<>'aifrogi_platform_admin' OR current_setting('app.system_purpose',true)<>'PLATFORM_ADMIN' OR p_actor IS DISTINCT FROM current_setting('app.security_actor',true) THEN RAISE EXCEPTION 'PLATFORM_ADMIN_CONTEXT_REQUIRED'; END IF; END $$;
CREATE FUNCTION aifrogi_security.record_governance_control(p_kind text,p_owner text,p_approver text,p_controls text[],p_rationale text,p_impact text,p_evidence jsonb,p_expires timestamptz,p_remediation timestamptz,p_digest text,p_actor text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE v_id text:=gen_random_uuid()::text; forbidden text[]:=ARRAY['TENANT_ISOLATION','CURRENT_AUTHORIZATION','NO_FACTUAL_FALLBACK','SECRET_HANDLING','TRANSACTION_AUTHORITY','EXACT_ANSWER_BINDING','TRUTHFUL_DELIVERY']; BEGIN PERFORM aifrogi_security.require_platform_admin(p_actor); IF p_owner=p_approver OR jsonb_array_length(p_evidence)=0 OR (p_kind='EXCEPTION' AND (p_controls&&forbidden OR p_expires<=clock_timestamp())) THEN RAISE EXCEPTION 'GOVERNANCE_CONTROL_INVALID'; END IF; INSERT INTO "GovernanceControlRecord" VALUES(v_id,p_kind,p_owner,p_approver,p_controls,p_rationale,p_impact,p_evidence,p_expires,p_remediation,p_digest,clock_timestamp()); RETURN v_id; END $$;
CREATE FUNCTION aifrogi_security.request_material_approval(p_action text,p_target text,p_hash text,p_requester text,p_expires timestamptz,p_actor text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE v_id text:=gen_random_uuid()::text; BEGIN PERFORM aifrogi_security.require_platform_admin(p_actor); IF p_expires<=clock_timestamp() THEN RAISE EXCEPTION 'APPROVAL_EXPIRY_INVALID'; END IF; INSERT INTO "MaterialApproval"(id,action,target,"payloadHash","requestedBy","expiresAt")VALUES(v_id,p_action,p_target,p_hash,p_requester,p_expires);RETURN v_id;END $$;
CREATE FUNCTION aifrogi_security.approve_material_action(p_id text,p_approver text,p_actor text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN PERFORM aifrogi_security.require_platform_admin(p_actor); UPDATE "MaterialApproval" SET state='APPROVED',"approvedBy"=p_approver WHERE id=p_id AND state='PENDING' AND "requestedBy"<>p_approver AND "expiresAt">clock_timestamp(); IF NOT FOUND THEN RAISE EXCEPTION 'TWO_PERSON_APPROVAL_DENIED'; END IF;END $$;
CREATE FUNCTION aifrogi_security.consume_material_approval(p_id text,p_action text,p_target text,p_hash text,p_actor text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN PERFORM aifrogi_security.require_platform_admin(p_actor); UPDATE "MaterialApproval" SET state='EXECUTED',"executedAt"=clock_timestamp() WHERE id=p_id AND state='APPROVED' AND action=p_action AND target=p_target AND "payloadHash"=p_hash AND "expiresAt">clock_timestamp(); IF NOT FOUND THEN RAISE EXCEPTION 'MATERIAL_APPROVAL_INVALID'; END IF;END $$;
CREATE FUNCTION aifrogi_security.queue_repair_command(p_property text,p_type text,p_key text,p_expected integer,p_reason text,p_payload jsonb,p_hash text,p_actor text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE v_id text; BEGIN PERFORM aifrogi_security.require_platform_admin(p_actor); SELECT id INTO v_id FROM "GovernedRepairCommand" WHERE "idempotencyKey"=p_key AND "payloadHash"=p_hash; IF v_id IS NOT NULL THEN RETURN v_id; END IF; IF EXISTS(SELECT 1 FROM "GovernedRepairCommand" WHERE "idempotencyKey"=p_key) THEN RAISE EXCEPTION 'IDEMPOTENCY_PAYLOAD_MISMATCH'; END IF; v_id:=gen_random_uuid()::text; INSERT INTO "GovernedRepairCommand"(id,"propertyId","commandType","idempotencyKey","expectedVersion",reason,payload,"payloadHash","requestedBy")VALUES(v_id,p_property,p_type,p_key,p_expected,p_reason,p_payload,p_hash,p_actor);RETURN v_id;END $$;
CREATE FUNCTION aifrogi_security.issue_break_glass(p_incident text,p_grantee text,p_scopes text[],p_reason text,p_expires timestamptz,p_actor text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE v_id text:=gen_random_uuid()::text; BEGIN PERFORM aifrogi_security.require_platform_admin(p_actor); INSERT INTO "BreakGlassGrant"(id,"incidentId","actorEmail",scopes,reason,"expiresAt")VALUES(v_id,p_incident,p_grantee,p_scopes,p_reason,p_expires);RETURN v_id;END $$;
CREATE FUNCTION aifrogi_security.review_break_glass(p_id text,p_reviewer text,p_actor text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN PERFORM aifrogi_security.require_platform_admin(p_actor); UPDATE "BreakGlassGrant" SET "reviewedBy"=p_reviewer,"reviewedAt"=clock_timestamp() WHERE id=p_id AND "actorEmail"<>p_reviewer AND "reviewedBy" IS NULL; IF NOT FOUND THEN RAISE EXCEPTION 'INDEPENDENT_BREAK_GLASS_REVIEW_REQUIRED'; END IF;END $$;
REVOKE ALL ON FUNCTION aifrogi_security.require_platform_admin(text),aifrogi_security.record_governance_control(text,text,text,text[],text,text,jsonb,timestamptz,timestamptz,text,text),aifrogi_security.request_material_approval(text,text,text,text,timestamptz,text),aifrogi_security.approve_material_action(text,text,text),aifrogi_security.consume_material_approval(text,text,text,text,text),aifrogi_security.queue_repair_command(text,text,text,integer,text,jsonb,text,text),aifrogi_security.issue_break_glass(text,text,text[],text,timestamptz,text),aifrogi_security.review_break_glass(text,text,text) FROM PUBLIC,aifrogi_web,aifrogi_public,aifrogi_worker,aifrogi_publisher;
GRANT EXECUTE ON FUNCTION aifrogi_security.record_governance_control(text,text,text,text[],text,text,jsonb,timestamptz,timestamptz,text,text),aifrogi_security.request_material_approval(text,text,text,text,timestamptz,text),aifrogi_security.approve_material_action(text,text,text),aifrogi_security.consume_material_approval(text,text,text,text,text),aifrogi_security.queue_repair_command(text,text,text,integer,text,jsonb,text,text),aifrogi_security.issue_break_glass(text,text,text[],text,timestamptz,text),aifrogi_security.review_break_glass(text,text,text) TO aifrogi_platform_admin;
